{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Tiotropium, a quaternary ammonium tropane epoxide ester structurally very similar to the query, has absolute oral bioavailability of only 2–3% in healthy volunteers, directly supporting F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Ipratropium, a quaternary ammonium tropane tropate ester, showed apparent systemic availability around 2% after oral dosing in healthy volunteers, supporting low oral bioavailability for this quaternary tropane class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Phenoperidine, an ester-containing basic drug, had oral bioavailability below 15% in healthy subjects, supporting poor oral systemic exposure for ester-containing basic drugs with first-pass liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Cyclandelate, a tropic acid ester without the quaternary ammonium, showed extremely low bioavailability in humans, supporting poor absorption of this ester scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "One ipratropium study reported about 32% oral absorption at a 30 mg dose, an outlier against multiple other ipratropium studies reporting ~2–3% F; it is contradictory but does not outweigh the consistent low-F data.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Pethidine, a tertiary amine phenylpiperidine ester, has ~50% oral bioavailability in healthy subjects; this is contradictory direction but less transferable because it lacks the permanent quaternary charge and tropane epoxide scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Prediction is low (F <20%). The query is a quaternary ammonium tropane epoxide tropate ester; direct absolute bioavailability data for closely related tiotropium (2–3%) and ipratropium (~2–3%) strongly indicate poor oral absorption. The permanent positive charge and ester scaffold are key liabilities. Contradictory higher-F examples are less transferable (tertiary amines, disease states, or outliers).",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule; extrapolation relies on closely related quaternary tropane analogs.",
    "One ipratropium study reported ~32% absorption at 30 mg, suggesting possible dose-dependent or methodological variability that is not fully resolved.",
    "Transporter-mediated efflux or intestinal secretion contributions are not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

